-- ----------------------------
-- Table structure for `lt_ssc_ds_yl`
-- ----------------------------
DROP TABLE IF EXISTS `lt_ssc_ds_yl`;
CREATE TABLE `lt_ssc_ds_yl` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `positions` varchar(8) DEFAULT NULL COMMENT '位置',
  `zhi` varchar(120) DEFAULT NULL COMMENT '值',
  `current_miss` smallint(8) DEFAULT NULL COMMENT '本期遗漏',
  `last_time_miss` smallint(8) DEFAULT NULL COMMENT '上次遗漏',
  `last_time_miss_range` varchar(64) DEFAULT NULL COMMENT '上次遗漏范围',
  `max_miss` tinyint(4) DEFAULT NULL COMMENT '最大遗漏(近200期)',
  `max_range` varchar(64) DEFAULT NULL COMMENT '最大遗漏范围(近200期)',
  `yl_records` text COMMENT '遗漏记录',
  `history_max_miss` smallint(8) DEFAULT NULL COMMENT '历史最大遗漏',
  `type` tinyint(1) DEFAULT NULL COMMENT '1一定2二定3三定4四定',
  `lottery_type` tinyint(4) DEFAULT '2' COMMENT '彩种类型：1:1.5分 2:3分 3:5分 4:10分|希腊、5:重庆ssc 6:新疆ssc',
  `created_at` int(11) DEFAULT NULL COMMENT '创建时间',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `positions` (`positions`),
  KEY `zhi` (`zhi`),
  KEY `type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8 COMMENT='定位单双遗漏表';

